} // onCreate Close

// ২. ক্লাসের বডি (Class Body)
private android.widget.ListView listView;
private android.widget.ProgressBar progressBar;
private MyAdapter myAdapter;
private String pendingPkg = "";

private void checkVpnAndStart() {
    android.content.Intent intent = android.net.VpnService.prepare(this);
    if (intent != null) {
        startActivityForResult(intent, 101);
    } else {
        showConfirmDialog(pendingPkg);
    }
}

@Override
protected void onActivityResult(int req, int res, android.content.Intent d) {
    if (req == 101 && res == RESULT_OK) {
        showConfirmDialog(pendingPkg);
    }
}

private void showConfirmDialog(final String pkg) {
    String name = ""; 
    try { name = getPackageManager().getApplicationLabel(getPackageManager().getApplicationInfo(pkg, 0)).toString(); } catch(Exception e) { name = pkg; }

    new android.app.AlertDialog.Builder(this)
        .setTitle("Confirmation")
        .setMessage("Do you want to block internet for " + name + "?")
        .setPositiveButton("Yes", (d, w) -> {
            CycleService.blockedApps.add(pkg);
            updateService();
        })
        .setNegativeButton("No", (d, w) -> {
            if (myAdapter != null) myAdapter.notifyDataSetChanged();
        })
        .setCancelable(false)
        .show();
}

private void updateService() {
    android.content.Intent it = new android.content.Intent(this, CycleService.class);
    it.setAction(CycleService.blockedApps.isEmpty() ? "STOP" : "START");
    startService(it);
    if (myAdapter != null) myAdapter.notifyDataSetChanged();
}

private void loadAppList() {
    progressBar.setVisibility(0);
    new Thread(() -> {
        android.content.pm.PackageManager pm = getPackageManager();
        android.content.Intent i = new android.content.Intent("android.intent.action.MAIN").addCategory("android.intent.category.LAUNCHER");
        java.util.List<android.content.pm.ResolveInfo> list = pm.queryIntentActivities(i, 0);
        java.util.Collections.sort(list, new android.content.pm.ResolveInfo.DisplayNameComparator(pm));
        final java.util.ArrayList<java.util.HashMap<String, Object>> data = new java.util.ArrayList<>();
        for (android.content.pm.ResolveInfo r : list) {
            if (r.activityInfo.packageName.equals(getPackageName())) continue;
            java.util.HashMap<String, Object> m = new java.util.HashMap<>();
            m.put("n", pm.getApplicationLabel(r.activityInfo.applicationInfo).toString());
            m.put("p", r.activityInfo.packageName);
            m.put("i", pm.getApplicationIcon(r.activityInfo.applicationInfo));
            data.add(m);
        }
        runOnUiThread(() -> { progressBar.setVisibility(8); myAdapter = new MyAdapter(data); listView.setAdapter(myAdapter); });
    }).start();
}

class MyAdapter extends android.widget.BaseAdapter {
    java.util.ArrayList<java.util.HashMap<String, Object>> _d;
    MyAdapter(java.util.ArrayList<java.util.HashMap<String, Object>> d) { _d = d; }
    @Override public int getCount() { return _d.size(); }
    @Override public Object getItem(int i) { return _d.get(i); }
    @Override public long getItemId(int i) { return i; }
    @Override public android.view.View getView(int i, android.view.View v, android.view.ViewGroup p) {
        if (v == null) {
            android.widget.LinearLayout l = new android.widget.LinearLayout(MainActivity.this);
            l.setPadding(25, 35, 25, 35); l.setGravity(16);
            android.widget.ImageView img = new android.widget.ImageView(MainActivity.this); l.addView(img, 110, 110);
            android.widget.TextView t = new android.widget.TextView(MainActivity.this); t.setPadding(35, 0, 0, 0); t.setTextSize(16);
            l.addView(t, new android.widget.LinearLayout.LayoutParams(0, -2, 1f));
            android.widget.Switch s = new android.widget.Switch(MainActivity.this); l.addView(s); v = l;
        }
        java.util.HashMap<String, Object> m = _d.get(i);
        final String pkg = m.get("p").toString();
        android.widget.Switch sw = (android.widget.Switch)((android.view.ViewGroup)v).getChildAt(2);
        ((android.widget.TextView)((android.view.ViewGroup)v).getChildAt(1)).setText(m.get("n").toString());
        ((android.widget.ImageView)((android.view.ViewGroup)v).getChildAt(0)).setImageDrawable((android.graphics.drawable.Drawable)m.get("i"));
        sw.setOnCheckedChangeListener(null);
        sw.setChecked(CycleService.blockedApps.contains(pkg));
        sw.setOnClickListener(view -> {
            if (CycleService.blockedApps.contains(pkg)) {
                CycleService.blockedApps.remove(pkg);
                updateService();
            } else {
                sw.setChecked(false);
                pendingPkg = pkg;
                checkVpnAndStart();
            }
        });
        return v;
    }
}

private void showMyLogs() {
    android.widget.ListView lv = new android.widget.ListView(this);
    lv.setAdapter(new android.widget.ArrayAdapter<>(this, android.R.layout.simple_list_item_1, CycleService.logList));
    new android.app.AlertDialog.Builder(this).setTitle("Blocked Requests").setView(lv).setPositiveButton("OK", null).show();
}

public static class CycleService extends android.net.VpnService {
    private android.os.ParcelFileDescriptor vpn = null;
    public static java.util.HashSet<String> blockedApps = new java.util.HashSet<>();
    public static java.util.ArrayList<String> logList = new java.util.ArrayList<>();

    @Override
    public int onStartCommand(android.content.Intent it, int f, int id) {
        if (it != null && "STOP".equals(it.getAction())) { stopVpn(); return START_NOT_STICKY; }
        if (blockedApps.isEmpty()) { stopVpn(); return START_NOT_STICKY; }
        establishVpn();
        return START_STICKY;
    }

    private void establishVpn() {
        try {
            if (vpn != null) vpn.close();
            Builder b = new Builder().setSession("NetBlocker").addAddress("10.0.0.2", 32);

            // সব ট্রাফিক ভিপিএন-এ টানার রুট
            b.addRoute("0.0.0.0", 0); 

            // সিলেক্ট করা অ্যাপগুলোকে এলাউ করা (এদের ট্রাফিক ভিপিএন জেলখানায় ঢুকবে)
            for (String pkg : blockedApps) { try { b.addAllowedApplication(pkg); } catch(Exception e) {} }

            // আমাদের মেইন অ্যাপকে ভিপিএন থেকে বাইরে রাখা (যাতে আমাদের অ্যাপে নেট থাকে)
            try { b.addDisallowedApplication(getPackageName()); } catch(Exception e) {}

            vpn = b.establish();
            showNotif("Blocking internet for " + blockedApps.size() + " apps...");

            new Thread(() -> {
                try (java.io.FileInputStream in = new java.io.FileInputStream(vpn.getFileDescriptor())) {
                    byte[] buf = new byte[2048];
                    while (vpn != null) {
                        int l = in.read(buf); // রিড হবে কিন্তু ফরওয়ার্ড হবে না = ব্লক!
                        if (l > 0) {
                            String d = new String(buf, 0, l, "UTF-8");
                            if (d.contains("Host:")) {
                                logList.add(0, "Blocked: " + d.substring(d.indexOf("Host:"), Math.min(d.length(), d.indexOf("Host:") + 35)).trim());
                            }
                        }
                    }
                } catch (Exception e) {}
            }).start();
        } catch (Exception e) {}
    }

    private void stopVpn() {
        try { if (vpn != null) vpn.close(); vpn = null; } catch (Exception e) {}
        stopForeground(true); stopSelf();
    }

    private void showNotif(String msg) {
        android.app.NotificationManager nm = (android.app.NotificationManager)getSystemService(NOTIFICATION_SERVICE);
        if (android.os.Build.VERSION.SDK_INT >= 26) nm.createNotificationChannel(new android.app.NotificationChannel("nb","Block",3));
        android.app.PendingIntent pi = android.app.PendingIntent.getActivity(this, 0, new android.content.Intent(this, MainActivity.class).setAction("SHOW_LOGS"), 201326592);
        startForeground(1, new android.app.Notification.Builder(this,"nb").setSmallIcon(android.R.drawable.ic_lock_lock).setContentTitle("NetBlocker Active").setContentText(msg).setContentIntent(pi).build());
    }

    @Override public void onDestroy() { stopVpn(); super.onDestroy(); }
}
